import{_ as l,p as i,q as e,Y as a}from"./framework-e1bed10d.js";const t={},r=a('<h1 id="_04内置函数" tabindex="-1"><a class="header-anchor" href="#_04内置函数" aria-hidden="true">#</a> 04内置函数</h1><p>函数是指一段可以被直接调用的程序或者代码</p><h2 id="聚合函数" tabindex="-1"><a class="header-anchor" href="#聚合函数" aria-hidden="true">#</a> 聚合函数</h2><p>分组查询中，经常会用到聚合函数，常见的聚合函数有以下几种：</p><ul><li>count(字段/*)：根据某个字段统计数量</li><li>max(字段)：某个字段为表中最大值的数据</li><li>min(字段)：某个字段为表中最小值的数据</li><li>avg(字段)：计算某个字段的平均值</li><li>sum(字段)：计算某个字段之和</li></ul><h2 id="字符串函数" tabindex="-1"><a class="header-anchor" href="#字符串函数" aria-hidden="true">#</a> 字符串函数</h2><ul><li>LEFT(str,len)：左边的len个字符</li><li>RIGHT(str,len)：右边的len个字符</li><li>CONCAT(S1,S2,...,Sn)：字符串拼接</li><li>LOWER(str)：转换为小写字符</li><li>UPPER(str)：转换为大写字符</li><li>LTRIM(str)：去除左边的空格</li><li>RTRIM(str)：去除右边的空格</li><li>TRIM(str)：去除字符串两边的空格</li><li>LENGTH(str)：长度</li><li>LPAD(str,len,s)：用s左填充str到长度len</li><li>RPAD(str,len,s)：用s右填充str到长度len</li><li>SUBSTRING(str,from,len)：从str截取字符串str的len个字符</li><li>OUNDEX()：转换为语音值</li></ul><h2 id="日期和时间处理" tabindex="-1"><a class="header-anchor" href="#日期和时间处理" aria-hidden="true">#</a> 日期和时间处理</h2><p>日期格式为<code>YYYY-MM-DD</code>，时间格式为<code>HH:MM:SS</code></p><ul><li>CurDate()：返回当前日期</li><li>CurTime()：返回当前时间</li><li>NOW()：当前的日期和时间</li><li>date_add(date,interval count type)：将日期增加count个type</li><li>Date_Format(date,format)：返回一个格式化的日期或时间串</li><li>DateDiff(date1, date2)：计算两个日期相差的天数，date1减date2</li><li>AddTime()：增加一个时间(时、分)等</li><li>Date(&#39;2020-12-12 22:23:12&#39;)：返回日期时间的日期部分</li><li>DayOfWeek(date)：对于一个日期，返回对应的星期几</li><li>Year(date)：返回一个日期的年份部分</li><li>Month(date)：返回一个日期的月份部分</li><li>Day(date)：返回一个日期的天数部分</li><li>Hour(date)：返回一个时间的小时部分</li><li>Minute(date)：返回一个时间的分钟部分</li><li>Second()：返回一个时间的秒部分</li><li>Time()：返回一个日期时间的时间部分</li></ul><h2 id="数值函数" tabindex="-1"><a class="header-anchor" href="#数值函数" aria-hidden="true">#</a> 数值函数</h2><ul><li>SIN()：正弦</li><li>COS()：余弦</li><li>TAN()：正切</li><li>ABS()：绝对值</li><li>SQRT()：平方根</li><li>MOD(x, y)：取x/y的模(余数)</li><li>FLOOR(X)：向下取整</li><li>CEIL(x)：向上取整</li><li>ROUND(x, y)：求参数x的四舍五入值，保留y位小数</li><li>EXP()：指数</li><li>PI()：圆周率</li><li>RAND()：0-1的随机数</li></ul><h2 id="流程函数" tabindex="-1"><a class="header-anchor" href="#流程函数" aria-hidden="true">#</a> 流程函数</h2><ul><li>if(value, t, f)：如果value为true，则返回t，否则返回f</li><li>ifnull(value1,value2)：如果value1不为空则返回，否则返回value2</li><li>case when exp then res1,...else [default] end：如果val1为true，则返回res1,..，否则返回default默认值，when和then可以有多个，以end结尾</li><li>case exp when val1 then res1,...else [default] end：如果exp等于val1，则返回res1,...，否则返回default默认值，when和then可以有多个，以end结尾</li></ul>',14),d=[r];function n(s,h){return i(),e("div",null,d)}const c=l(t,[["render",n],["__file","04function.html.vue"]]);export{c as default};
